"""Independent naive reference for the telemetry compiler (dev only)."""
import itertools

OPS = {'eq': lambda a, b: a == b, 'ne': lambda a, b: a != b,
       'lt': lambda a, b: a < b, 'le': lambda a, b: a <= b,
       'gt': lambda a, b: a > b, 'ge': lambda a, b: a >= b}


def ref_compile(job):
    fields = job['fields']
    K = job['slots']
    names = {f['name']: i for i, f in enumerate(fields)}
    nf = len(fields)
    domains = [fields[i]['domain'] for _ in range(K) for i in range(nf)]

    # universe in lex order of flattened cells (cell0 most significant)
    universe = [list(w) for w in itertools.product(*domains)]

    def pos(ref):
        return ref[0] * nf + names[ref[1]]

    def term(t, row):
        if 'const' in t:
            return t['const']
        if 'sum' in t:
            return sum(row[pos(r)] for r in t['sum'])
        if 'scale' in t:
            return t['scale'] * row[pos(t['ref'])]
        return row[pos(t['ref'])]

    def pred(p, row):
        if p['kind'] == 'cmp':
            return OPS[p['op']](term(p['left'], row), term(p['right'], row))
        fi = names[p['field']]
        cmp = OPS[p['op']]
        vals = [row[s * nf + fi] for s in range(K)]
        if p['kind'] == 'any':
            return any(cmp(v, p['value']) for v in vals)
        return all(cmp(v, p['value']) for v in vals)

    train = [list(itertools.chain.from_iterable(w)) for w in job['train']]
    P = len(job['predicates'])
    tm = [[pred(p, r) for p in job['predicates']] for r in train]
    um = [[pred(p, r) for p in job['predicates']] for r in universe]

    rules = []
    for size in range(1, job['width'] + 1):
        for clause in itertools.combinations(range(P), size):
            ok = True
            witnesses = []
            for x, i in enumerate(clause):
                wit = None
                for t in range(len(train)):
                    if tm[t][i] and not any(tm[t][j] for j in clause if j != i):
                        wit = t
                        break
                if wit is None:
                    ok = False
                    break
                witnesses.append(wit)
            if not ok:
                continue
            for t in range(len(train)):
                if not any(tm[t][i] for i in clause):
                    ok = False
                    break
            if not ok:
                continue
            ce = None
            for u in range(len(universe)):
                if not any(um[u][i] for i in clause):
                    ce = u
                    break
            if ce is None:
                continue
            rules.append({'clause': list(clause), 'witnesses': witnesses,
                          'counterexample': ce})
    rules.sort(key=lambda r: (len(r['clause']), r['clause']))
    approved = {tuple(c) for c in job['approved']}
    active = [r['clause'] for r in rules if tuple(r['clause']) in approved]

    answers = []
    for q in job['queries']:
        tcell = pos(q['target'])
        fixed = {pos(b['ref']): b['value'] for b in q['fixed']}
        prefix = q['prefix']
        count = 0
        wit = None
        tokens = set()
        for u, row in enumerate(universe):
            if any(row[c] != v for c, v in fixed.items()):
                continue
            if not all(any(pred(job['predicates'][i], row) for i in cl)
                       for cl in active):
                continue
            spell = str(row[tcell])
            if not spell.startswith(prefix):
                continue
            count += 1
            if wit is None:
                wit = u
            if len(spell) == len(prefix):
                tokens.add('END')
            else:
                tokens.add(spell[len(prefix)])
        ordered = [str(d) for d in range(10) if str(d) in tokens]
        if 'END' in tokens:
            ordered.append('END')
        answers.append({'count': count, 'tokens': ordered, 'witness': wit})
    return {'rules': rules, 'active': active, 'answers': answers}
