"""Randomized differential test of the engine against the naive reference."""
import ctypes, sys, json, random
ctypes.CDLL('/workspace/vendor/system-libs/libz.so.1', mode=ctypes.RTLD_GLOBAL)
sys.path.insert(0, '/workspace/vendor')
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/dev')
from netnomos.finite import compile_job
from reference import ref_compile

TYPES = ['time', 'size', 'count', 'id', 'flag']

def gen_job(rng):
    nf = rng.randint(1, 3)
    K = rng.randint(1, 3)
    fields = []
    for i in range(nf):
        t = rng.choice(TYPES)
        size = rng.randint(1, 4)
        domain = sorted(rng.sample(range(0, 12), size))
        fields.append({'name': f'f{i}', 'type': t, 'domain': domain})
    cells = K * nf
    def rand_ref():
        return [rng.randrange(K), rng.choice(fields)['name']]
    P = rng.randint(0, 8)
    preds = []
    for _ in range(P):
        kind = rng.choice(['cmp', 'cmp', 'cmp', 'any', 'all', 'cmp'])
        if kind == 'cmp':
            def rand_term(depth=0):
                r = rng.random()
                if r < 0.4:
                    return {'ref': rand_ref()}
                if r < 0.6:
                    return {'const': rng.randint(0, 15), 'type': rng.choice(['time','size','count','id','flag'])}
                if r < 0.8 and depth == 0:
                    n = rng.randint(1, 3)
                    refs = []
                    seen = set()
                    for _ in range(n):
                        ref = rand_ref()
                        k = tuple(ref)
                        while k in seen:
                            ref = rand_ref(); k = tuple(ref)
                        seen.add(k)
                        refs.append(ref)
                    return {'sum': refs}
                return {'scale': rng.randint(0, 20), 'ref': rand_ref()}
            preds.append({'kind': 'cmp', 'left': rand_term(), 'op': rng.choice(list(OPS := ['eq','ne','lt','le','gt','ge'])), 'right': rand_term()})
        else:
            f = rng.choice(fields)
            op = rng.choice(['eq','ne'] if f['type'] in ('id','flag') else ['eq','ne','lt','le','gt','ge'])
            preds.append({'kind': kind, 'field': f['name'], 'op': op, 'value': rng.randint(0, 15)})
    width = rng.randint(1, 4)
    ntrain = rng.randint(1, 8)
    train = [[[rng.choice(f['domain']) for f in fields] for _ in range(K)] for _ in range(ntrain)]
    approved = []
    for _ in range(rng.randint(0, 5)):
        size = rng.randint(1, width)
        cl = sorted(rng.sample(range(P), size)) if P >= size else []
        if cl and cl not in approved:
            approved.append(cl)
    queries = []
    for _ in range(rng.randint(0, 5)):
        fixed = []
        cells_refs = [[s, f['name']] for s in range(K) for f in fields]
        rng.shuffle(cells_refs)
        nf_fixed = rng.randint(0, min(3, len(cells_refs) - 1))
        for ref in cells_refs[:nf_fixed]:
            fi = names_i = [f['name'] for f in fields].index(ref[1])
            fixed.append({'ref': ref, 'value': rng.choice(fields[fi]['domain'])})
        target = cells_refs[nf_fixed]
        prefix = rng.choice(['', '0', '1', '10', '01', '3', '7777777', '12'])
        queries.append({'target': target, 'prefix': prefix, 'fixed': fixed})
    return {'fields': fields, 'slots': K, 'predicates': preds, 'width': width,
            'train': train, 'approved': approved, 'queries': queries}

def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    iters = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rng = random.Random(seed)
    for it in range(iters):
        job = gen_job(rng)
        a = compile_job(job)
        b = ref_compile(job)
        if a != b:
            print('MISMATCH at iteration', it)
            print(json.dumps(job))
            print('engine:', json.dumps(a))
            print('ref:   ', json.dumps(b))
            sys.exit(1)
    print('fuzz OK', iters, 'iterations, seed', seed)

if __name__ == '__main__':
    main()
